package org.slavicmyths.sanctuary;
import java.util.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.level.block.Rotation;
public final class SanctuaryChecks {
 static int checks;static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 static void vanillaPalette(CompoundTag palette){var id=net.minecraft.resources.ResourceLocation.parse(palette.getString("Name"));if(!id.getNamespace().equals("minecraft"))return;var block=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getOptional(id);check(block.isPresent(),"vanilla block "+id);for(String key:palette.getCompound("Properties").getAllKeys()){var property=block.orElseThrow().getStateDefinition().getProperty(key);check(property!=null&&property.getValue(palette.getCompound("Properties").getString(key)).isPresent(),"native state property "+id+"/"+key);}}
 public static void main(String[] args)throws Exception{
  check(SanctuaryTerrain.floor(List.of(64,64,64),false,7).orElseThrow()==64,"flat fire floor");check(SanctuaryTerrain.floor(List.of(64,65,68,70),false,7).orElseThrow()==68,"gentle hill fire");check(SanctuaryTerrain.floor(List.of(64,65,68,70),true,7).orElseThrow()==46,"spring uses lowest roof-support column");check(SanctuaryTerrain.floor(List.of(64,72),false,7).isEmpty(),"steep terrain rejected");check(SanctuaryTerrain.floor(List.of(62,64),false,7).isEmpty(),"low/wet coast rejected");check(SanctuaryTerrain.floor(List.of(64,131),false,100).isEmpty(),"world height policy");check(SanctuaryTerrain.floor(List.of(74,74),true,7).isEmpty(),"spring below allowed depth rejected");check(SanctuaryTerrain.floor(List.of(),true,7).isEmpty(),"empty footprint rejected");
  int healing=0;for(int remaining=160;remaining>=1;remaining--)if(SanctuaryRules.healTick(remaining))healing++;check(healing==8&&!SanctuaryRules.healTick(160)&&SanctuaryRules.healTick(1),"eight delayed 1HP heals");check(SanctuaryRules.shortened(100)==65&&SanctuaryRules.shortened(1)==1,"partial water never full removal");check(SanctuaryRules.guardDuration(40,.3)==28,"30% duration guard");
  for(boolean spring:new boolean[]{false,true})for(var r:Rotation.values()){var origin=SanctuaryGeometry.root(new BlockPos(100,46,-100),spring,r);var box=SanctuaryGeometry.box(origin,r,0,0,0,SanctuaryGeometry.width(spring)-1,26,SanctuaryGeometry.depth(spring)-1);check(box.minX()==100&&box.minZ()==-100,"normalized rotation origin");var points=new HashSet<BlockPos>();for(int x=0;x<SanctuaryGeometry.width(spring);x++)for(int z=0;z<SanctuaryGeometry.depth(spring);z++){var p=origin.offset(SanctuaryGeometry.rotate(x,0,z,r));if(!points.add(p)||!box.isInside(p))throw new AssertionError("rotation overlap/bounds");}check(points.size()==SanctuaryGeometry.width(spring)*SanctuaryGeometry.depth(spring),"bijection "+r);check(SanctuaryGeometry.guardian(origin,spring,r).isInside(SanctuaryGeometry.spawnAnchor(origin,spring,r)),"future anchor bounds");}
  var d=new SanctuaryRecords();UUID id=UUID.randomUUID(),player=UUID.randomUUID(),other=UUID.randomUUID();d.ensure(id,new BlockPos(100,64,100),Rotation.CLOCKWISE_90,false);check(d.restore(id)&&!d.restore(id),"one shared fire restoration");check(d.claim(id,player)&&!d.claim(id,player)&&d.claim(id,other),"independent one-time actor receipts");UUID water=UUID.randomUUID();d.ensure(water,new BlockPos(100,46,100),Rotation.NONE,true);check(d.pool(water,0)&&!d.pool(water,0)&&!d.cleansed(water),"first pool single-shot");check(d.pool(water,1)&&d.cleansed(water),"two pools complete");var saved=d.save(new CompoundTag(),null);var restored=SanctuaryRecords.load(saved,null);check(restored.restored(id)&&restored.cleansed(water)&&!restored.claim(id,player),"persistent shared flags and receipts");check(restored.row(id).getIntArray("GuardianBounds").length==6&&restored.row(id).getString("RelicDoorState").equals("SEALED_193"),"real reserved chamber metadata");
  net.neoforged.fml.loading.LoadingModList.of(List.of(),List.of(),List.of(),List.of(),Map.of());net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();
  var registry=(net.minecraft.core.MappedRegistry<net.minecraft.world.level.block.Block>)net.minecraft.core.registries.BuiltInRegistries.BLOCK;registry.unfreeze();var holders=net.minecraft.core.MappedRegistry.class.getDeclaredField("unregisteredIntrusiveHolders");holders.setAccessible(true);holders.set(registry,new java.util.IdentityHashMap<>());
  for(String kind:List.of("seal_fire_door","seal_spring_door","carved_fire_pillar","carved_spring_pillar","fire_idol_sun","fire_idol_tree","fire_idol_circle")){var decor=new SanctuaryDecor(kind);check(decor.getStateDefinition().getPossibleStates().size()==8,"decor eight states "+kind);for(var state:decor.getStateDefinition().getPossibleStates())check(!state.hasProperty(net.minecraft.world.level.block.RotatedPillarBlock.AXIS),"decor has no log axis "+kind);}

  int tiles=0,markers=0,blocks=0;try(var paths=Files.walk(Path.of("src/main/resources/data/slavicmyths/structure/sanctuaries"))){for(var path:paths.filter(p->p.toString().endsWith(".nbt")).toList()){var tag=NbtIo.readCompressed(path,NbtAccounter.unlimitedHeap());int[] size={tag.getList("size",3).getInt(0),tag.getList("size",3).getInt(1),tag.getList("size",3).getInt(2)};check(size[0]<=16&&size[2]<=16&&size[1]==27,"bounded native tile");var palette=tag.getList("palette",10);for(var p:palette)vanillaPalette((CompoundTag)p);var seen=new HashSet<String>();for(var raw:tag.getList("blocks",10)){var b=(CompoundTag)raw;var pos=b.getList("pos",3);int x=pos.getInt(0),y=pos.getInt(1),z=pos.getInt(2);if(x<0||x>=size[0]||y<0||y>=size[1]||z<0||z>=size[2]||b.getInt("state")>=palette.size()||!seen.add(x+","+y+","+z))throw new AssertionError("native position/palette duplicate");if(b.getCompound("nbt").getString("mode").equals("DATA"))markers++;blocks++;}check(tag.getList("entities",10).isEmpty(),"no future boss entities");tiles++;}}
  check(tiles==61&&markers==13,"61 templates / 13 one-time markers");System.out.println("SANCTUARY_OFFLINE_PASS checks="+checks+" nativeTiles="+tiles+" markers="+markers+" authoredBlocks="+blocks+"; no game launch; NBT is not relog; synthetic terrain is not seed QA");
 }
}
